<?php
$all_cash = 0; $all_bank = 0;
foreach ($totals as $code => $total) { if ($category === '' || $category === $code) { $all_cash += $total['cash']; $all_bank += $total['bank']; } }
$kind_labels = array('income' => 'Bevétel', 'expense' => 'Kiadás', 'transfer' => 'Átvezetés', 'opening' => 'Nyitóegyenleg');
?>
<section class="heading"><div><p class="eyebrow">Pénzügyeid, egy helyen</p><h1>Áttekintés<?php echo $category ? ' · ' . cash_e($category) : ''; ?></h1><p class="muted">Egyenlegek <?php echo cash_e($date); ?> nap végén<?php echo $date > date('Y-m-d') ? ' · tervezett állapot' : ''; ?>.</p></div><a class="button" href="<?php echo url('/transaction'); ?>">+ Új tétel</a></section>
<form method="get" class="filters panel">
  <label>Egyenleg dátuma<input type="date" name="date" value="<?php echo cash_e($date); ?>" required></label>
  <label>Kategória<select name="category"><option value="">B + P + W</option><?php foreach (array('B','P','W') as $code) { ?><option<?php echo $category === $code ? ' selected' : ''; ?>><?php echo $code; ?></option><?php } ?></select></label>
  <label>Tranzakciók számlája<select name="account_id"><option value="0">Összes számla</option><?php foreach ($accounts as $account) { ?><option value="<?php echo (int) $account['id']; ?>"<?php echo $account_id == $account['id'] ? ' selected' : ''; ?>><?php echo cash_e($account['name']); ?></option><?php } ?></select></label>
  <button type="submit" class="secondary">Mutasd</button><a href="<?php echo url('/'); ?>">Ma</a>
</form>
<div class="summary-grid"><article class="panel hero"><p>Összes pénz</p><strong><?php echo cash_format($all_cash + $all_bank, $main_currency); ?></strong><small><?php echo $category ? cash_e($category) : 'B + P + W'; ?> · a választott napon</small></article><article class="panel"><p>Készpénz és borítékok</p><strong><?php echo cash_format($all_cash, $main_currency); ?></strong><small>Készpénznek jelölt zsebekben</small></article><article class="panel"><p>Számlákon</p><strong><?php echo cash_format($all_bank, $main_currency); ?></strong><small>Nem készpénzes számlákon</small></article></div>
<div class="category-grid"><?php foreach ($totals as $code => $total) { ?><article class="panel category-card<?php echo $category === $code ? ' selected' : ''; ?>"><span class="badge category-<?php echo strtolower($code); ?>"><?php echo $code; ?></span><strong><?php echo cash_format($total['cash'] + $total['bank'], $main_currency); ?></strong><dl><div><dt>KP</dt><dd><?php echo cash_format($total['cash'], $main_currency); ?></dd></div><div><dt>Számlán</dt><dd><?php echo cash_format($total['bank'], $main_currency); ?></dd></div></dl></article><?php } ?></div>
<div class="section-heading"><h2>Számlák és zsebek</h2><a href="<?php echo url('/accounts'); ?>">Kezelés →</a></div>
<?php if (!count($accounts)) { ?><div class="panel empty"><h3>Hol tartod a pénzed?</h3><p>Vegyél fel például egy OTP-s számlát, egy pénztárcát és egy készpénzes borítékot.</p><a class="button" href="<?php echo url('/accounts'); ?>">Első számla hozzáadása</a></div><?php } else { ?>
<div class="account-grid"><?php foreach ($accounts as $account) {
  $balance = 0; $main_balance = 0;
  foreach (array('B','P','W') as $code) { if (($category === '' || $code === $category) && isset($balances[$account['id']][$code])) { $balance += $balances[$account['id']][$code]['amount']; $main_balance += $balances[$account['id']][$code]['main_amount']; } }
  if ($account['archived'] && $balance == 0 && $main_balance == 0) { continue; }
?><article class="panel account-card"><div class="section-heading"><h3><?php echo cash_e($account['name']); ?></h3><span class="pill"><?php echo $account['is_cash'] ? 'KP' : 'Számla'; ?></span></div><strong><?php echo cash_format($balance, $account['currency']); ?></strong><?php if ($account['currency'] !== $main_currency) { ?><small><?php echo cash_format($main_balance, $main_currency); ?> · rögzített érték</small><?php } ?><dl><?php foreach (array('B','P','W') as $code) { ?><div><dt><?php echo $code; ?></dt><dd><?php echo cash_format(isset($balances[$account['id']][$code]) ? $balances[$account['id']][$code]['amount'] : 0, $account['currency']); ?></dd></div><?php } ?></dl><?php if ($account['archived']) { ?><small>Archivált</small><?php } ?></article><?php } ?></div><?php } ?>
<p class="hint">A fődevizás összesítés a tételeknél rögzített átváltásokat használja, nem élő árfolyamot. A kategóriaszűrő az összesített és a számlaegyenlegeket is szűri; a B/P/W bontás mindig teljes.</p>
<div class="section-heading"><div><h2>Tranzakciók</h2><p class="muted">Múltbeli és jövőbeli tételek. A kiemelt napig számítanak az egyenlegbe.</p></div></div>
<div class="panel ledger"><?php if (!count($transactions)) { ?><div class="empty"><h3>Még nincs tétel ebben a listában.</h3><p>Kezdj egy nyitóegyenleggel, aztán jöhetnek a bevételek és a kiadások.</p></div><?php } else { foreach ($transactions as $transaction) { ?>
<article class="ledger-row<?php echo $transaction['booked_on'] > $date ? ' excluded' : ''; ?>"><div class="ledger-date"><time><?php echo cash_e($transaction['booked_on']); ?></time><?php if ($transaction['booked_on'] > date('Y-m-d')) { ?><span class="pill">Tervezett</span><?php } ?><?php if ($transaction['booked_on'] > $date) { ?><small>Az egyenlegen kívül</small><?php } ?></div><div class="ledger-detail"><a class="transaction-title" href="<?php echo url('/transaction?id=' . (int) $transaction['id']); ?>"><?php echo cash_e($transaction['note'] !== '' ? $transaction['note'] : $kind_labels[$transaction['kind']]); ?></a><small><?php echo $kind_labels[$transaction['kind']]; ?> · Eredeti: <?php echo cash_format(cash_stored_amount($transaction['original_amount']), $transaction['original_currency']); ?></small><?php foreach ($legs[$transaction['id']] as $leg) { ?><div class="leg"><span class="badge category-<?php echo strtolower($leg['category']); ?>"><?php echo cash_e($leg['category']); ?></span><span><?php echo cash_e($leg['name']); ?></span><b class="<?php echo $leg['amount'] < 0 ? 'negative' : 'positive'; ?>"><?php echo $leg['amount'] > 0 ? '+' : ''; ?><?php echo cash_format(cash_stored_amount($leg['amount']), $leg['currency']); ?></b><?php if ($leg['currency'] !== $main_currency) { ?><small><?php echo cash_format(cash_stored_amount($leg['main_amount']), $main_currency); ?></small><?php } ?></div><?php } ?></div><a class="edit-link" href="<?php echo url('/transaction?id=' . (int) $transaction['id']); ?>">Szerkesztés</a></article>
<?php } } ?></div>
<?php if ($page_count > 1) { ?><nav class="pagination" aria-label="Lapozás"><?php if ($page > 1) { ?><a href="<?php echo cash_e(url('/?' . http_build_query(array('date' => $date, 'category' => $category, 'account_id' => $account_id, 'page' => $page - 1)))); ?>">← Előző</a><?php } ?><span><?php echo $page . ' / ' . $page_count; ?></span><?php if ($page < $page_count) { ?><a href="<?php echo cash_e(url('/?' . http_build_query(array('date' => $date, 'category' => $category, 'account_id' => $account_id, 'page' => $page + 1)))); ?>">Következő →</a><?php } ?></nav><?php } ?>
